sections.body:
保存下面为 wave-archive.mjs，用 node wave-archive.mjs 运行，无额外依赖。导入候选时先解析 JSON，并限制批量大小、校验数组和对象结构；本例代码继续检查时间与 ID。非法结构抛错，超过在场上限计为 rejected，合格但时间表相同计为 duplicates。相同内容保留最先出现的记录。

```js
/**
 * @file 用固定寿命的教学波次演示分格归档，不模拟真实战斗。
 * @author liliwei
 * @date 2026-11-06
 * @LastEditors liliwei
 * @LastEditTime 2026-11-06
 */

/**
 * 计算教学波次的时间特征与目标分；怪物在 [出生, 出生+3) 存在。
 * @param {number[]} times 六个 0–17 的整数出生秒数，可同时出生。
 * @returns {object} 排序副本、规则通过标记、特征、分数及格子键。
 */
export function measureWave(times) {
  if (!Array.isArray(times) || times.length !== 6 ||
      [...times].some(t => !Number.isInteger(t) || t < 0 || t > 17)) {
    throw new Error('需要六个 0–17 的整数');
  }
  const sorted = [...times].sort((a, b) => a - b);
  const alive = Array.from({ length: 20 }, (_, t) =>
    sorted.filter(s => s <= t && t < s + 3).length);
  const early = sorted.filter(t => t < 10).length;
  const peak = Math.max(...alive), end = sorted[5] + 3;
  return { times: sorted, valid: peak <= 3, early, peak, end,
    score: 20 - Math.abs(end - 18),
    cell: `${early >= 3 ? 1 : 0},${peak >= 3 ? 1 : 0}` };
}

/**
 * 先按规则与内容去重，再保留每格得分最高者；同分取较小 ASCII ID。
 * @param {{id:string,times:number[]}[]} rows 候选数组，ID 为唯一的大写字母。
 * @returns {object} 合格候选、格子代表及两类剔除计数。
 */
export function archiveWaves(rows) {
  const ids = new Set(), seen = new Set(), cells = new Map();
  const valid = [];
  let rejected = 0, duplicates = 0;
  for (const row of rows) {
    if (!row || !/^[A-Z]+$/.test(row.id) || ids.has(row.id)) {
      throw new Error('ID 必须是唯一的大写字母串');
    }
    ids.add(row.id);
    const item = { id: row.id, ...measureWave(row.times) };
    if (!item.valid) { rejected++; continue; }
    const key = item.times.join(',');
    if (seen.has(key)) { duplicates++; continue; }
    seen.add(key); valid.push(item);
    const old = cells.get(item.cell);
    if (!old || item.score > old.score ||
        (item.score === old.score && item.id < old.id)) cells.set(item.cell, item);
  }
  return { valid, elites: [...cells.values()], rejected, duplicates };
}

// 全部为手工候选；I 是 A 的乱序副本，J 违反同时在场上限。
export const samples = [
  ['A', [0, 3, 6, 10, 12, 15]], ['B', [0, 3, 6, 11, 13, 15]],
  ['C', [1, 4, 7, 10, 13, 15]], ['D', [2, 5, 8, 11, 14, 15]],
  ['E', [0, 1, 2, 10, 12, 14]], ['F', [0, 10, 11, 13, 14, 16]],
  ['G', [0, 10, 11, 12, 15, 17]], ['H', [0, 1, 2, 3, 15, 17]],
  ['I', [15, 12, 10, 6, 3, 0]], ['J', [0, 0, 0, 0, 15, 16]],
].map(([id, times]) => ({ id, times }));
const result = archiveWaves(samples);
const top = [...result.valid].sort((a, b) =>
  b.score - a.score || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)).slice(0, 4);
console.log(JSON.stringify({ rejected: result.rejected, duplicates: result.duplicates,
  top: top.map(x => x.id), topCells: new Set(top.map(x => x.cell)).size,
  archive: result.elites.map(x => x.id), archiveCells: result.elites.length }));
console.table(result.elites.map(({ id, early, peak, end, score, cell }) =>
  ({ id, early, peak, end, score, cell })));
```

分数只用于同格替换；新类型即使分数较低也能入空格。模型不能自报 early、peak 或 score，它们必须由当前版本的评估器重算。正式导出还应经过策划批准，不能把入格等同于可以上线。
